{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ampicillin absolute oral bioavailability in humans was 48.1 ± 19.3%, clearly above the 20% threshold, and this high-transfer evidence supports high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Meperidine absolute oral bioavailability was 0.60 versus IV in subjects, providing direct human evidence of high oral bioavailability that transfers strongly to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Diphenhydramine absolute oral bioavailability was 58% in humans, supporting high oral bioavailability for the query through a high-transfer analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Felbamate absolute oral bioavailability was >90% in humans, a strong high-bioavailability anchor with high transferability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Perindopril absolute oral bioavailability was about 75% in humans, supporting high oral bioavailability despite ester prodrug character, relevant to the query's ester functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Rivastigmine absolute oral bioavailability was 71.7% after a 6 mg capsule in patients, supporting high oral bioavailability for a drug with substantial first-pass metabolism, analogous to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "PEMA absolute oral bioavailability was 91 ± 4.4% in normal volunteers, providing high-transfer evidence of high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide absolute oral bioavailability was 60% in healthy subjects, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "DEHP oral bioavailability was about 25% in human volunteers, still above the 20% threshold and supportive of high classification even for a lower-bioavailability compound.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved high-transfer experimental records report human oral bioavailability values at or above 25%, with most above 50%; no affirmative evidence of F < 20% was found. The query, a tropane ester (scopolamine-like), may have borderline oral bioavailability near 20-30% due to first-pass metabolism, but the available transferable evidence supports classification as high at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself was supplied.",
    "The query's oral bioavailability may be near the 20% threshold, and no low-bioavailability analogue was available to test the contrast."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

